JANGDAN_COUNT = 4
TURN_TAKING = {'sequence_per_pair': ['expert', 'ready', 'student'], 'lead_in_jangdan': 1}

def jangdan_for(song_id):
    song = SONGS[song_id]
    jd = dict(JANGDAN[song['jangdan']])
    if song.get('bpm_bak'):
        jd['bpm_bak'] = song['bpm_bak']
        jd['tempo_source'] = song.get('tempo_source', jd.get('tempo_source', ''))
    if song.get('jangdan_audio'):
        jd['audio'] = song['jangdan_audio']
        jd['audio_note'] = song.get('jangdan_audio_note', '')
    return jd

def jangdan_count(song_id):
    return SONGS[song_id].get('jangdan_count', JANGDAN_COUNT)

def grid_downbeat(song_id, role):
    v = (SONGS[song_id].get('reference') or {}).get('grid_first_downbeat_s')
    return v[role] if isinstance(v, dict) else v

def grid_cycle(song_id, role):
    v = (SONGS[song_id].get('reference') or {}).get('grid_cycle_s')
    v = v[role] if isinstance(v, dict) else v
    return None if v is None else float(v)

def use_jangdan(song_id):
    ref = SONGS[song_id].get('reference') or {}
    start = ref.get('start_jangdan', 1)
    return [start, start + jangdan_count(song_id) - 1]

def measures_voice(song_id):
    s = SONGS[song_id]
    return bool(s.get('accent_feedback') or s.get('breath_feedback'))
